package com.erudit.quiz;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.quiz.controller.QuizController;import com.erudit.quiz.model.QuizModels.*;import com.erudit.quiz.openapi.model.*;import com.erudit.quiz.service.QuizService;import java.util.*;import org.junit.jupiter.api.Test;
class QuizControllerTest {@Test void exposesQuizFlow(){var service=mock(QuizService.class);var controller=new QuizController(service);UUID quiz=UUID.randomUUID(),attempt=UUID.randomUUID();var q=new Quiz(quiz,"Daily");when(service.list()).thenReturn(List.of(q));when(service.daily()).thenReturn(q);when(service.create(any(),any(),any(),anyInt(),any())).thenReturn(q);when(service.start(eq(quiz),any())).thenReturn(new Attempt(attempt,quiz,UUID.randomUUID(),"STARTED",null,0));when(service.hint(attempt)).thenReturn(new QuizService.Hint("Hint",1));when(service.submit(attempt,1)).thenReturn(new Attempt(attempt,quiz,UUID.randomUUID(),"COMPLETED",1,1));assertThat(controller.listQuizzes().getBody()).hasSize(1);controller.dailyQuiz();controller.createQuiz(new QuizRequest("T","P",List.of("A","B"),1,"H"));controller.startQuiz(quiz,null);assertThat(controller.quizHint(attempt).getBody().getRemaining()).isOne();assertThat(controller.submitQuiz(attempt,new QuizSubmitRequest(1)).getBody().getScore()).isOne();}}
